// =============================================================================
// ==== rtl/router/bypass_source.sv
// =============================================================================
`timescale 1ns/1ps

module bypass_source
  import noc_pkg::*;
#(
  parameter int MESH_N = 8,
  parameter int NUM_VC = 4,                         // 1..4
  parameter int B_MAX  = 10,                        // flits per burst, 5..15
  parameter int NP     = NPORTS * NUM_VC,           // derived, do not set
  parameter int KW     = $clog2(NPORTS * NUM_VC)    // derived, do not set
) (
  input  logic                           clk_i,
  input  logic                           rst_ni,
  input  coord_t                         cur_x_i,      // this router
  input  coord_t                         cur_y_i,
  input  logic                           tx_go_i,
  input  node_id_t                       tx_dst_i,     // the partner
  input  logic                           tx_mode_i,    // MODE_XY or MODE_YX
  input  logic                           cancel_i,
  input  logic  [NPORTS-1:0][NUM_VC-1:0] rdy_i,        // whole packet waiting, nothing sent
  input  flit_t [NPORTS-1:0][NUM_VC-1:0] front_i,      // front flit of every VC
  output logic  [NPORTS-1:0][NUM_VC-1:0] hold_o,       // packets taken now
  output logic  [NPORTS-1:0][NUM_VC-1:0] pop_o,        // flit leaving now
  output logic                           xb_en_o,
  output flit_t                          xb_flit_o,
  output port_t                          xb_port_o,
  output logic  [NPORTS-1:0]             in_mask_o,
  output logic  [NPORTS-1:0]             out_mask_o,
  output logic                           la_vld_o,
  output port_t                          la_port_o,
  output la_t                            la_o,
  output logic                           busy_o        // a burst is streaming
);

  localparam int RW = 1 + PKT_LEN_W;     // eligibility record: {ok, length}
  localparam int RB = NP * RW;           // all records
  localparam int SW = 5;                 // running sum: B_MAX + 5 <= 20 < 32

  logic [NP-1:0]      sel_q;     // packets of the burst still to send
  logic [KW-1:0]      ptr_q;     // where the next choice starts its scan
  logic [KW-1:0]      start_q;   // where this burst's scan started: its order
  port_t              port_q;    // first-hop output of the burst
  logic [BURST_W-1:0] rem_q;     // flits of the burst still to send
  logic               cx_q;      // a cancel token for the next turn

  flit_t           fr [NP];
  logic [NP*RW-1:0] rec;         // record k at bits [k*RW +: RW]

  always_comb begin
    /* verilator lint_off UNUSEDSIGNAL */
    head_t h;                    // only dst and len are read
    /* verilator lint_on UNUSEDSIGNAL */
    for (int p = 0; p < NPORTS; p++) begin
      for (int v = 0; v < NUM_VC; v++) begin
        h                                = head_t'(front_i[p][v].data);
        fr[p * NUM_VC + v]               = front_i[p][v];
        rec[(p * NUM_VC + v) * RW +: RW] = {rdy_i[p][v] && (h.dst == tx_dst_i), h.len};
      end
    end
  end

  logic [2*RB-1:0] rec2;
  logic [RB-1:0]   rrec;

  assign rec2 = {rec, rec};
  assign rrec = RB'(rec2 >> (ptr_q * RW));

  logic [NP-1:0] tk;             // taken, in scan order
  logic [SW-1:0] sum;

  always_comb begin
    logic [SW-1:0] nx;
    sum = '0;
    for (int m = 0; m < NP; m++) begin
      nx    = sum + SW'(rrec[m * RW +: PKT_LEN_W]);
      tk[m] = rrec[m * RW + PKT_LEN_W] && (nx <= SW'(B_MAX));
      if (tk[m]) sum = nx;
    end
  end

  logic [2*NP-1:0]    tk2;
  logic [NP-1:0]      take;
  logic [BURST_W-1:0] blen;
  logic               go;
  port_t              p1;

  assign tk2  = {tk, tk};
  assign take = NP'(tk2 >> (NP - int'(ptr_q)));
  assign blen = BURST_W'(sum);
  assign go   = tx_go_i && !cx_q && (sum != '0);
  assign p1   = dor_port(cur_x_i, cur_y_i, id_x(tx_dst_i, MESH_N), id_y(tx_dst_i, MESH_N), tx_mode_i);

  logic [2*NP-1:0] sel2;
  logic [NP-1:0]   srot;
  logic [KW-1:0]   m0, cur;
  logic            strm;         // a flit leaves this cycle
  logic            last_of_pkt;  // it is a tail

  assign sel2 = {sel_q, sel_q};
  assign srot = NP'(sel2 >> start_q);

  always_comb begin
    int cs;
    m0 = '0;
    for (int m = NP - 1; m >= 0; m--) begin
      if (srot[m]) m0 = KW'(m);                     // the lowest set bit wins
    end
    cs = int'(start_q) + int'(m0);
    if (cs >= NP) cs = cs - NP;
    cur         = KW'(cs);
    strm        = (sel_q != '0);
    last_of_pkt = is_tail(fr[cur].ftype);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sel_q   <= '0;
      ptr_q   <= '0;
      start_q <= '0;
      port_q  <= P_L;
      rem_q   <= '0;
      cx_q    <= 1'b0;
    end else begin
      if (go) begin
        sel_q   <= take;
        start_q <= ptr_q;
        ptr_q   <= (int'(ptr_q) == NP - 1) ? '0 : ptr_q + 1'b1;
        port_q  <= p1;
        rem_q   <= blen;
      end else if (strm) begin
        if (last_of_pkt) sel_q[cur] <= 1'b0;
        rem_q <= rem_q - 1'b1;
      end
      if (tx_go_i)       cx_q <= 1'b0;              // the turn the token was for
      else if (cancel_i) cx_q <= 1'b1;
    end
  end

  always_comb begin
    hold_o     = '0;
    pop_o      = '0;
    in_mask_o  = '0;
    out_mask_o = '0;
    for (int p = 0; p < NPORTS; p++) begin
      for (int v = 0; v < NUM_VC; v++) begin
        hold_o[p][v] = go && take[p * NUM_VC + v];
        pop_o[p][v]  = strm && (int'(cur) == p * NUM_VC + v);
      end
    end
    if (go || rem_q >= BURST_W'(2)) in_mask_o[P_L] = 1'b1;
    if (go)                         out_mask_o[p1] = 1'b1;
    if (rem_q >= BURST_W'(2))       out_mask_o[port_q] = 1'b1;
    if (strm) in_mask_o[int'(cur) / NUM_VC] = 1'b1;
  end

  always_comb begin
    xb_en_o         = strm;
    xb_port_o       = port_q;
    xb_flit_o       = fr[cur];
    xb_flit_o.vld   = strm;
    xb_flit_o.vc    = '0;
    xb_flit_o.byp   = 1'b1;
    la_vld_o        = go;
    la_port_o       = p1;
    la_o            = '0;
    la_o.vld        = go;
    la_o.dst        = tx_dst_i;
    la_o.mode       = tx_mode_i;
    la_o.len        = blen;
  end

  assign busy_o = strm || cx_q;

`ifndef SYNTHESIS
  // `ifndef SYNTHESIS only, outside the synthesis-off pragmas: every
  longint unsigned n_turns;          // subslots in which this router may send
  longint unsigned n_used;           // ... and sent a burst
  longint unsigned n_cxl;            // ... cancelled by a token from the destination
  longint unsigned n_lost;           // ... cancelled while packets for the partner waited
  longint unsigned n_flits;          // flits sent by bypass
  longint unsigned n_pkts;           // packets sent by bypass
  longint unsigned n_multi;          // bursts of two or more packets
  longint unsigned n_remote;         // packets taken from a port other than Local
  longint unsigned n_full;           // bursts of exactly B_MAX flits
  longint unsigned n_b2b;            // bursts chosen while the last one sent its last flit

  int unsigned     n_take_all, n_take_mesh;
  always_comb begin
    n_take_all  = 0;
    n_take_mesh = 0;
    for (int k = 0; k < NP; k++) begin
      if (take[k]) begin
        n_take_all = n_take_all + 1;
        if (k < NP - NUM_VC) n_take_mesh = n_take_mesh + 1;
      end
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      n_turns  <= 0;
      n_used   <= 0;
      n_cxl    <= 0;
      n_lost   <= 0;
      n_flits  <= 0;
      n_pkts   <= 0;
      n_multi  <= 0;
      n_remote <= 0;
      n_full   <= 0;
      n_b2b    <= 0;
    end else begin
      if (tx_go_i) n_turns <= n_turns + 1;
      if (tx_go_i && cx_q) begin
        n_cxl <= n_cxl + 1;
        if (sum != '0) n_lost <= n_lost + 1;
      end
      if (go && strm) n_b2b <= n_b2b + 1;
      if (go) begin
        n_used   <= n_used + 1;
        n_flits  <= n_flits + longint'(sum);
        n_pkts   <= n_pkts + longint'(n_take_all);
        n_remote <= n_remote + longint'(n_take_mesh);
        if (n_take_all > 1)         n_multi <= n_multi + 1;
        if (int'(sum) == B_MAX)     n_full  <= n_full + 1;
      end
    end
  end

  // synopsys translate_off
  initial begin
    if (NUM_VC < 1 || NUM_VC > MAX_VC)
      $fatal(1, "%m: NUM_VC = %0d, must be 1..%0d", NUM_VC, MAX_VC);
    if (B_MAX < MAX_PKT_FLITS || B_MAX > MAX_BURST)
      $fatal(1, "%m: B_MAX = %0d, must hold a %0d-flit packet and be at most %0d", B_MAX, MAX_PKT_FLITS, MAX_BURST);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      if ($isunknown({tx_go_i, cancel_i}))
        $fatal(1, "%m: X on tx_go_i or cancel_i");
      if (cancel_i && cx_q)
        $fatal(1, "%m: a second cancel token arrived before the turn the first one cancels");
      if (cancel_i && tx_go_i)
        $fatal(1, "%m: a cancel token arrived in the cycle of the turn itself, too late (D38)");
      if (go) begin
        if (tx_dst_i == xy_to_id(cur_x_i, cur_y_i, MESH_N))
          $fatal(1, "%m: the timetable makes this router send to itself");
        if (strm && !(rem_q == BURST_W'(1) && $countones(sel_q) == 1 && last_of_pkt))
          $fatal(1, "%m: a burst starts while the previous one still has %0d flits to send", rem_q);
      end
      if (strm) begin
        if (!fr[cur].vld)
          $fatal(1, "%m: bypass reads VC %0d of port %0d, which is empty", int'(cur) % NUM_VC, int'(cur) / NUM_VC);
        if (rem_q == '0)
          $fatal(1, "%m: the burst sends more flits than its lookahead announced");
        if ($countones(sel_q) == 1 && last_of_pkt && rem_q != BURST_W'(1))
          $fatal(1, "%m: the burst ends with %0d announced flits unsent", int'(rem_q) - 1);
      end else if (rem_q != '0) begin
        $fatal(1, "%m: %0d announced flits never sent", rem_q);
      end
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/bypass_relay.sv
// =============================================================================
`timescale 1ns/1ps

module bypass_relay
  import noc_pkg::*;
#(
  parameter int MESH_N = 8,
  parameter int B_MAX  = 10                 // largest burst, flits
) (
  input  logic                clk_i,
  input  logic                rst_ni,
  input  coord_t              cur_x_i,      // this router
  input  coord_t              cur_y_i,
  input  la_t   [3:0]         la_i,
  input  flit_t [3:0]         flit_i,
  input  logic                src_la_vld_i,
  input  port_t               src_la_port_i,
  input  la_t                 src_la_i,
  output logic  [3:0]         xb_en_o,
  output flit_t [3:0]         xb_flit_o,
  output port_t [3:0]         xb_port_o,
  output logic  [NPORTS-1:0]  in_mask_o,
  output logic  [NPORTS-1:0]  out_mask_o,
  output la_t   [3:0]         la_o,
  output la_t                 la_loc_o,
  output logic                busy_o        // a burst or lookahead is inside
);

  port_t              la_port [4];      // output of an arriving lookahead
  logic [BURST_W-1:0] cnt_q   [4];      // flits of the burst still to come
  port_t              out_q   [4];      // their output

  always_comb begin
    for (int p = 0; p < 4; p++)
      la_port[p] = dor_port(cur_x_i, cur_y_i, id_x(la_i[p].dst, MESH_N), id_y(la_i[p].dst, MESH_N), la_i[p].mode);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      for (int p = 0; p < 4; p++) begin
        cnt_q[p] <= '0;
        out_q[p] <= P_L;
      end
    end else begin
      for (int p = 0; p < 4; p++) begin
        if (la_i[p].vld) begin
          cnt_q[p] <= la_i[p].len;
          out_q[p] <= la_port[p];
        end else if (cnt_q[p] != '0) begin
          cnt_q[p] <= cnt_q[p] - 1'b1;
        end
      end
    end
  end

  always_comb begin
    in_mask_o  = '0;
    out_mask_o = '0;
    for (int p = 0; p < 4; p++) begin
      xb_en_o[p]   = (cnt_q[p] != '0);
      xb_port_o[p] = out_q[p];
      xb_flit_o[p] = flit_i[p];
      if (la_i[p].vld) begin
        in_mask_o[p]           = 1'b1;
        out_mask_o[la_port[p]] = 1'b1;
      end
      if (cnt_q[p] >= BURST_W'(2)) begin
        in_mask_o[p]         = 1'b1;
        out_mask_o[out_q[p]] = 1'b1;
      end
    end
  end

  la_t  [3:0] st_d;
  logic [3:0] st_vld_q, lt_vld_q;
  la_t  [3:0] st_q, lt_q;

  always_comb begin
    for (int q = 0; q < 4; q++) begin
      st_d[q] = '0;
      if (src_la_vld_i && int'(src_la_port_i) == q) st_d[q] = src_la_i;
      for (int p = 0; p < 4; p++) begin
        if (la_i[p].vld && int'(la_port[p]) == q) st_d[q] = la_i[p];
      end
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      st_vld_q <= '0;
      lt_vld_q <= '0;
    end else begin
      for (int q = 0; q < 4; q++) begin
        st_vld_q[q] <= st_d[q].vld;
        lt_vld_q[q] <= st_vld_q[q];
      end
    end
  end

  always_ff @(posedge clk_i) begin
    for (int q = 0; q < 4; q++) begin
      if (st_d[q].vld)  st_q[q] <= st_d[q];
      if (st_vld_q[q])  lt_q[q] <= st_q[q];
    end
  end

  always_comb begin
    for (int q = 0; q < 4; q++) begin
      la_o[q]     = lt_q[q];
      la_o[q].vld = lt_vld_q[q];
    end
  end

  always_comb begin
    la_loc_o = '0;
    for (int p = 0; p < 4; p++) begin
      if (la_i[p].vld && la_port[p] == P_L) la_loc_o = la_i[p];
    end
  end

  always_comb begin
    busy_o = (st_vld_q != '0) || (lt_vld_q != '0);
    for (int p = 0; p < 4; p++) busy_o = busy_o || (cnt_q[p] != '0);
  end

`ifndef SYNTHESIS
  // pragmas):
  longint unsigned n_abut;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      n_abut <= 0;
    end else begin
      for (int p = 0; p < 4; p++) begin
        if (la_i[p].vld && cnt_q[p] == BURST_W'(1)) n_abut <= n_abut + 1;
      end
    end
  end

  // synopsys translate_off
  initial begin
    if (B_MAX < 1 || B_MAX > MAX_BURST)
      $fatal(1, "%m: B_MAX = %0d, must be 1..%0d", B_MAX, MAX_BURST);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
    end else begin
      for (int q = 0; q < 4; q++) begin
        if (int'(src_la_vld_i && int'(src_la_port_i) == q) +
            int'(la_i[0].vld && int'(la_port[0]) == q) + int'(la_i[1].vld && int'(la_port[1]) == q) +
            int'(la_i[2].vld && int'(la_port[2]) == q) + int'(la_i[3].vld && int'(la_port[3]) == q) > 1)
          $fatal(1, "%m: two lookaheads for output %0d in one cycle", q);
      end
      if (int'(la_i[0].vld && la_port[0] == P_L) + int'(la_i[1].vld && la_port[1] == P_L) +
          int'(la_i[2].vld && la_port[2] == P_L) + int'(la_i[3].vld && la_port[3] == P_L) > 1)
        $fatal(1, "%m: two lookaheads for the Local output in one cycle");
      if (src_la_vld_i && int'(src_la_port_i) >= 4)
        $fatal(1, "%m: the source launches a lookahead on port %0d", src_la_port_i);
      for (int p = 0; p < 4; p++) begin
        if ($isunknown({la_i[p].vld, flit_i[p].vld}))
          $fatal(1, "%m: X on the lookahead or flit valid of input %0d", p);
        if (la_i[p].vld) begin
          if (la_i[p].len == '0 || int'(la_i[p].len) > B_MAX)
            $fatal(1, "%m: lookahead on input %0d announces %0d flits (B_MAX %0d)", p, la_i[p].len, B_MAX);
          if (int'(la_i[p].dst) >= MESH_N * MESH_N)
            $fatal(1, "%m: lookahead on input %0d for router %0d, outside the mesh", p, la_i[p].dst);
          if (la_port[p] == port_t'(p))
            $fatal(1, "%m: lookahead on input %0d would turn back out of the same port", p);
          if (cnt_q[p] >= BURST_W'(2))
            $fatal(1, "%m: lookahead on input %0d while %0d flits of the last burst are still to come", p, cnt_q[p]);
        end
        if (cnt_q[p] != '0 && !(flit_i[p].vld && flit_i[p].byp))
          $fatal(1, "%m: burst flit missing on input %0d (%0d still announced)", p, cnt_q[p]);
        if (cnt_q[p] == '0 && flit_i[p].vld && flit_i[p].byp)
          $fatal(1, "%m: bypass flit on input %0d without a lookahead", p);
      end
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/ni/resv_ctrl.sv
// =============================================================================
`timescale 1ns/1ps

module resv_ctrl
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int B_MAX = 10,                 // flits per burst
  parameter int SPACE = 28,                 // bypass space of the FIFO, flits (D48)
  parameter int GAP0  = s_setup(8),         // decision -> start of subslot 0
  parameter int GAPK  = t_tight(8, 10),     // decision -> start of a later subslot
  parameter int GAP0_L = GAP0,              // the same for the local timetable (designs C, D)
  parameter int GAPK_L = GAPK,
  parameter int CW    = $clog2(SPACE + 1)   // derived, do not set
) (
  input  logic          clk_i,
  input  logic          rst_ni,
  input  logic          dec_i,
  input  logic          dec_s0_i,           // the next subslot is subslot 0
  input  logic          dec_loc_i,          // ... of the local timetable (designs C, D)
  input  node_id_t      dec_src_i,          // its source
  input  logic          dec_mode_i,         // the mode of its path
  input  hop_t          dec_hops_i,         // its length L
  input  la_t           la_i,
  input  logic          push_i,
  input  logic          pop_i,
  output cx_t           cx_o,
  output logic [CW-1:0] res_o,
  output logic [CW-1:0] fill_o
);

  localparam int TW = 8;                    // countdown: GAP + 2L - 1 <= 127 + 60

  logic [CW-1:0] res_q, fill_q;
  logic [1:0]    w_vld_q;                   // reservations waiting for their lookahead
  logic [TW-1:0] w_cnt_q [2];               // cycles until each one is due
  logic          ok, acc, cxl, any_due, slot;
  logic [1:0]    due;
  logic [TW-1:0] load;
  int            res_n, gap;

  always_comb begin
    ok      = int'(fill_q) + int'(res_q) + B_MAX <= SPACE;
    acc     = dec_i && ok;
    cxl     = dec_i && !ok;
    due[0]  = w_vld_q[0] && (w_cnt_q[0] == '0);
    due[1]  = w_vld_q[1] && (w_cnt_q[1] == '0);
    any_due = |due;
    res_n   = int'(res_q);
    if (acc) res_n = res_n + B_MAX;
    if (any_due) begin
      if (la_i.vld) res_n = res_n - (B_MAX - int'(la_i.len));
      else          res_n = res_n - B_MAX;
    end
    if (push_i) res_n = res_n - 1;
  end

  assign slot = w_vld_q[0];
  always_comb begin
    if (dec_loc_i) gap = dec_s0_i ? GAP0_L : GAPK_L;
    else           gap = dec_s0_i ? GAP0 : GAPK;
  end
  assign load = TW'(gap + 2 * int'(dec_hops_i) - 1);

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      res_q      <= '0;
      fill_q     <= '0;
      w_vld_q    <= '0;
      w_cnt_q[0] <= '0;
      w_cnt_q[1] <= '0;
    end else begin
      res_q  <= CW'(res_n);
      fill_q <= CW'(int'(fill_q) + int'(push_i) - int'(pop_i));
      for (int i = 0; i < 2; i++) begin
        if (due[i])          w_vld_q[i] <= 1'b0;
        else if (w_vld_q[i]) w_cnt_q[i] <= w_cnt_q[i] - 1'b1;
      end
      if (acc) begin
        if (slot) begin
          w_vld_q[1] <= 1'b1;
          w_cnt_q[1] <= load;
        end else begin
          w_vld_q[0] <= 1'b1;
          w_cnt_q[0] <= load;
        end
      end
    end
  end

  always_comb begin
    cx_o      = '0;
    cx_o.vld  = cxl;
    cx_o.tgt  = dec_src_i;
    cx_o.mode = !dec_mode_i;
  end

  assign res_o  = res_q;
  assign fill_o = fill_q;

  logic unused_la;
  assign unused_la = ^{la_i.dst, la_i.mode, la_i.vc};

`ifndef SYNTHESIS
  // pragmas): decisions, accepted, cancelled, no-shows, lookaheads matched,
  longint unsigned n_dec, n_acc, n_cxl, n_noshow, n_la, n_in, n_two;
  int unsigned     max_fill, max_res, max_sum;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      n_dec    <= 0;
      n_acc    <= 0;
      n_cxl    <= 0;
      n_noshow <= 0;
      n_la     <= 0;
      n_in     <= 0;
      n_two    <= 0;
      max_fill <= 0;
      max_res  <= 0;
      max_sum  <= 0;
    end else begin
      if (dec_i)                n_dec    <= n_dec + 1;
      if (acc)                  n_acc    <= n_acc + 1;
      if (cxl)                  n_cxl    <= n_cxl + 1;
      if (any_due && !la_i.vld) n_noshow <= n_noshow + 1;
      if (any_due && la_i.vld)  n_la     <= n_la + 1;
      if (push_i)               n_in     <= n_in + 1;
      if (acc && w_vld_q != '0) n_two    <= n_two + 1;
      if (int'(fill_q) > int'(max_fill))               max_fill <= int'(fill_q);
      if (int'(res_q) > int'(max_res))                 max_res  <= int'(res_q);
      if (int'(fill_q) + int'(res_q) > int'(max_sum))  max_sum  <= int'(fill_q) + int'(res_q);
    end
  end

  // synopsys translate_off
  int unsigned idle_q;                      // cycles reserved flits have not come
  initial begin
    if (SPACE < B_MAX)
      $fatal(1, "%m: SPACE = %0d cannot hold one burst of B_MAX = %0d flits", SPACE, B_MAX);
    if (GAP0 < 1 || GAPK < 1 || GAP0 + 2 * hmax(MAX_MESH_N) > (1 << TW) || GAPK + 2 * hmax(MAX_MESH_N) > (1 << TW))
      $fatal(1, "%m: GAP0 = %0d, GAPK = %0d do not fit the %0d-bit countdown", GAP0, GAPK, TW);
    if (GAP0_L < 1 || GAPK_L < 1 || GAP0_L + 2 * hmax(MAX_MESH_N) > (1 << TW) || GAPK_L + 2 * hmax(MAX_MESH_N) > (1 << TW))
      $fatal(1, "%m: GAP0_L = %0d, GAPK_L = %0d do not fit the %0d-bit countdown", GAP0_L, GAPK_L, TW);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      idle_q <= 0;
    end else begin
      if ($isunknown({dec_i, la_i.vld, push_i, pop_i}) || (dec_i && $isunknown({dec_s0_i, dec_loc_i})))
        $fatal(1, "%m: X on dec_i, dec_s0_i, dec_loc_i, la_i.vld, push_i or pop_i");
      if (dec_i && (w_vld_q == 2'b11))
        $fatal(1, "%m: a third reservation waits for its lookahead");
      if (dec_i && any_due)
        $fatal(1, "%m: a decision in the cycle a lookahead is due (2L >= T?)");
      if (dec_i && dec_hops_i == '0)
        $fatal(1, "%m: a burst of 0 hops (from this router to itself)");
      if (due == 2'b11)
        $fatal(1, "%m: two reservations due in one cycle");
      if (la_i.vld && !any_due)
        $fatal(1, "%m: lookahead of a burst from nowhere reserved (%0d flits): the source ignored a cancel token?", la_i.len);
      if (la_i.vld && (la_i.len == '0 || int'(la_i.len) > B_MAX))
        $fatal(1, "%m: lookahead announces %0d flits (B_MAX %0d)", la_i.len, B_MAX);
      if (res_n < 0)
        $fatal(1, "%m: more bypass flits arrived than were reserved");
      if (pop_i && fill_q == '0)
        $fatal(1, "%m: the core took a bypass flit, but none is in the FIFO");
      if (int'(fill_q) + int'(res_q) > SPACE)
        $fatal(1, "%m: fill %0d + reserved %0d exceed the bypass space %0d", fill_q, res_q, SPACE);
      if (res_q == '0 || push_i || any_due || w_vld_q != '0) idle_q <= 0;
      else                                                  idle_q <= idle_q + 1;
      if (idle_q > 2)
        $fatal(1, "%m: %0d reserved flits have not come for %0d cycles (timeout)", res_q, idle_q);
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/router/cancel_relay.sv
// =============================================================================
`timescale 1ns/1ps

module cancel_relay
  import noc_pkg::*;
#(
  parameter int MESH_N = 8
) (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  coord_t      cur_x_i,       // this router
  input  coord_t      cur_y_i,
  input  cx_t  [3:0]  cx_i,          // tokens on the four mesh inputs (N, E, S, W)
  input  cx_t         inj_i,         // this router's own token (its NI cancels a burst)
  output cx_t  [3:0]  cx_o,          // tokens on the four mesh outputs
  output logic        hit_o,         // a token for this router: its next turn is cancelled
  output logic        busy_o         // a token is in one of the registers
);

  node_id_t   me;
  port_t      in_port [4];           // output of a token arriving on input p
  port_t      inj_port;              // output of the router's own token
  logic [3:0] in_hit;                // the token on input p is for this router
  cx_t  [3:0] st_d;
  logic [3:0] vld_q;
  cx_t  [3:0] cx_q;

  assign me = xy_to_id(cur_x_i, cur_y_i, MESH_N);

  always_comb begin
    for (int p = 0; p < 4; p++) begin
      in_port[p] = dor_port(cur_x_i, cur_y_i, id_x(cx_i[p].tgt, MESH_N), id_y(cx_i[p].tgt, MESH_N), cx_i[p].mode);
      in_hit[p]  = cx_i[p].vld && (cx_i[p].tgt == me);
    end
    inj_port = dor_port(cur_x_i, cur_y_i, id_x(inj_i.tgt, MESH_N), id_y(inj_i.tgt, MESH_N), inj_i.mode);
    for (int q = 0; q < 4; q++) begin
      st_d[q] = '0;
      if (inj_i.vld && int'(inj_port) == q) st_d[q] = inj_i;
      for (int p = 0; p < 4; p++) begin
        if (cx_i[p].vld && !in_hit[p] && int'(in_port[p]) == q) st_d[q] = cx_i[p];
      end
    end
  end

  assign hit_o = |in_hit;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      vld_q <= '0;
    end else begin
      for (int q = 0; q < 4; q++) vld_q[q] <= st_d[q].vld;
    end
  end

  always_ff @(posedge clk_i) begin
    for (int q = 0; q < 4; q++) begin
      if (st_d[q].vld) cx_q[q] <= st_d[q];
    end
  end

  always_comb begin
    for (int q = 0; q < 4; q++) begin
      cx_o[q]     = cx_q[q];
      cx_o[q].vld = vld_q[q];
    end
  end

  assign busy_o = (vld_q != '0);

`ifndef SYNTHESIS
  // pragmas): tokens launched here, forwarded, and delivered to this router
  longint unsigned n_inj, n_fwd, n_hit;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      n_inj <= 0;
      n_fwd <= 0;
      n_hit <= 0;
    end else begin
      if (inj_i.vld) n_inj <= n_inj + 1;
      if (hit_o)     n_hit <= n_hit + 1;
      for (int p = 0; p < 4; p++) begin
        if (cx_i[p].vld && !in_hit[p]) n_fwd <= n_fwd + 1;
      end
    end
  end

  // synopsys translate_off
  always_ff @(posedge clk_i or negedge rst_ni) begin
    int n_out, n_in;
    if (!rst_ni) begin
    end else begin
      if ($isunknown({inj_i.vld, cx_i[0].vld, cx_i[1].vld, cx_i[2].vld, cx_i[3].vld}))
        $fatal(1, "%m: X on a cancel token valid bit");
      if (inj_i.vld && (inj_i.tgt == me || int'(inj_i.tgt) >= MESH_N * MESH_N))
        $fatal(1, "%m: this router's NI launches a cancel token for router %0d", inj_i.tgt);
      n_in = 0;
      for (int p = 0; p < 4; p++) begin
        if (cx_i[p].vld) begin
          if (int'(cx_i[p].tgt) >= MESH_N * MESH_N)
            $fatal(1, "%m: cancel token on input %0d for router %0d, outside the mesh", p, cx_i[p].tgt);
          if (!in_hit[p] && int'(in_port[p]) == p)
            $fatal(1, "%m: cancel token on input %0d would turn back out of the same port", p);
        end
        if (in_hit[p]) n_in++;
      end
      if (n_in > 1)
        $fatal(1, "%m: %0d cancel tokens for this router in one cycle", n_in);
      for (int q = 0; q < 4; q++) begin
        n_out = 0;
        if (inj_i.vld && int'(inj_port) == q) n_out++;
        for (int p = 0; p < 4; p++) begin
          if (cx_i[p].vld && !in_hit[p] && int'(in_port[p]) == q) n_out++;
        end
        if (n_out > 1)
          $fatal(1, "%m: %0d cancel tokens for output %0d in one cycle", n_out, q);
      end
    end
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/sched/phase_sequencer.sv
// =============================================================================
`timescale 1ns/1ps

module phase_sequencer
  import sched_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int REGION_N = 4,
  parameter int T_SUB_G  = t_tight(8, 10),   // global subslot, cycles
  parameter int T_SUB_L  = t_tight(4, 10),   // local subslot, cycles
  parameter int K_INIT   = 4,                // k_L from reset
  parameter int EPOCH    = 1 << 15,          // epoch, cycles
  parameter int A_DLY    = A_DELAY,          // epoch tick -> plan sampled
  parameter int EW       = $clog2(EPOCH)     // derived, do not set
) (
  input  logic    clk_i,
  input  logic    rst_ni,
  input  kl_t     plan_i,        // k_L for the frames after the next sample
  output logic    loc_o,         // the local timetable runs this cycle
  output slot_t   slot_l_o,      // local counter
  output sub_t    sub_l_o,
  output sub_t    nxt_sub_l_o,
  output slot_t   slot_g_o,      // global counter
  output sub_t    sub_g_o,
  output sub_t    nxt_sub_g_o,
  output logic    sub_go_o,      // first cycle of a subslot (running timetable)
  output logic    nxt_go_o,      // cancel decision for its next subslot
  output kl_t     kl_o,          // k_L of the current frame
  output logic    tick_o,        // first cycle of an epoch
  output seq_st_t st_o           // whole state (testbench)
);

  logic [EW-1:0] ep_q;
  logic          samp;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni)                         ep_q <= '0;
    else if (ep_q == EW'(EPOCH - 1))     ep_q <= '0;
    else                                 ep_q <= ep_q + 1'b1;
  end

  assign tick_o = (ep_q == '0);
  assign samp   = (ep_q == EW'(A_DLY - 1));

  if (REGION_N == MESH_N) begin : g_one
    logic              g_setup, g_go, g_last, g_ngo;
    sub_t              g_sub, g_nsub;
    logic [TCYC_W-1:0] g_cyc;
    slot_t             g_slot;

    slot_counter #(
      .TT_N    (MESH_N),
      .T_SUB   (T_SUB_G),
      .S_SETUP (s_setup(MESH_N))
    ) u_glb (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .en_i        (1'b1),
      .setup_o     (g_setup),
      .sub_o       (g_sub),
      .cyc_o       (g_cyc),
      .slot_o      (g_slot),
      .sub_go_o    (g_go),
      .slot_last_o (g_last),
      .nxt_go_o    (g_ngo),
      .nxt_sub_o   (g_nsub)
    );

    assign loc_o       = 1'b0;
    assign slot_l_o    = '0;
    assign sub_l_o     = '0;
    assign nxt_sub_l_o = '0;
    assign slot_g_o    = g_slot;
    assign sub_g_o     = g_sub;
    assign nxt_sub_g_o = g_nsub;
    assign sub_go_o    = g_go;
    assign nxt_go_o    = g_ngo;
    assign kl_o        = '0;

    always_comb begin
      st_o         = '0;
      st_o.g_setup = g_setup;
      st_o.g_sub   = g_sub;
      st_o.g_cyc   = g_cyc;
      st_o.g_slot  = g_slot;
    end

    logic unused_one;
    assign unused_one = ^{g_last, samp, plan_i};
  end else begin : g_two
    logic              l_setup, l_go, l_last, l_ngo;
    logic              g_setup, g_go, g_last, g_ngo;
    sub_t              l_sub, l_nsub, g_sub, g_nsub;
    logic [TCYC_W-1:0] l_cyc, g_cyc;
    slot_t             l_slot, g_slot;
    logic              loc_q, pend_vld_q, apply;
    kl_t               k_q, lc_q, pend_q, k_nxt, k_new;

    slot_counter #(
      .TT_N    (REGION_N),
      .T_SUB   (T_SUB_L),
      .S_SETUP (s_setup(REGION_N))
    ) u_loc (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .en_i        (loc_q),
      .setup_o     (l_setup),
      .sub_o       (l_sub),
      .cyc_o       (l_cyc),
      .slot_o      (l_slot),
      .sub_go_o    (l_go),
      .slot_last_o (l_last),
      .nxt_go_o    (l_ngo),
      .nxt_sub_o   (l_nsub)
    );

    slot_counter #(
      .TT_N    (MESH_N),
      .T_SUB   (T_SUB_G),
      .S_SETUP (s_setup(MESH_N))
    ) u_glb (
      .clk_i       (clk_i),
      .rst_ni      (rst_ni),
      .en_i        (!loc_q),
      .setup_o     (g_setup),
      .sub_o       (g_sub),
      .cyc_o       (g_cyc),
      .slot_o      (g_slot),
      .sub_go_o    (g_go),
      .slot_last_o (g_last),
      .nxt_go_o    (g_ngo),
      .nxt_sub_o   (g_nsub)
    );

    assign k_nxt = samp ? plan_i : pend_q;
    assign apply = g_last && (samp || pend_vld_q);
    assign k_new = apply ? k_nxt : k_q;

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        loc_q      <= (K_INIT != 0);
        k_q        <= kl_t'(K_INIT);
        lc_q       <= '0;
        pend_q     <= '0;
        pend_vld_q <= 1'b0;
      end else begin
        if (samp) begin
          pend_q     <= plan_i;
          pend_vld_q <= 1'b1;
        end
        if (apply) pend_vld_q <= 1'b0;
        if (l_last) begin                     // a local slot ends ...
          if (lc_q == k_q - 1'b1) begin       // ... the frame's last: the global slot is next
            loc_q <= 1'b0;
            lc_q  <= '0;
          end else begin
            lc_q  <= lc_q + 1'b1;
          end
        end
        if (g_last) begin                     // the frame ends
          k_q   <= k_new;
          loc_q <= (k_new != '0);
          lc_q  <= '0;
        end
      end
    end

    assign loc_o       = loc_q;
    assign slot_l_o    = l_slot;
    assign sub_l_o     = l_sub;
    assign nxt_sub_l_o = l_nsub;
    assign slot_g_o    = g_slot;
    assign sub_g_o     = g_sub;
    assign nxt_sub_g_o = g_nsub;
    assign sub_go_o    = l_go | g_go;
    assign nxt_go_o    = l_ngo | g_ngo;
    assign kl_o        = k_q;

    always_comb begin
      st_o.loc     = loc_q;
      st_o.kl      = k_q;
      st_o.lc      = lc_q;
      st_o.l_setup = l_setup;
      st_o.l_sub   = l_sub;
      st_o.l_cyc   = l_cyc;
      st_o.l_slot  = l_slot;
      st_o.g_setup = g_setup;
      st_o.g_sub   = g_sub;
      st_o.g_cyc   = g_cyc;
      st_o.g_slot  = g_slot;
    end

`ifndef SYNTHESIS
    // synopsys translate_off
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
      end else begin
        if (samp && $isunknown(plan_i))
          $fatal(1, "%m: X on plan_i when it is sampled");
        if (loc_q && k_q == '0)
          $fatal(1, "%m: local phase with k_L = 0");
        if (int'(lc_q) >= int'(k_q) && k_q != '0)
          $fatal(1, "%m: %0d local slots finished in a frame of k_L = %0d", lc_q, k_q);
      end
    end
    // synopsys translate_on
`endif
  end

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (REGION_N < 2 || !pow2(REGION_N) || REGION_N > MESH_N || MESH_N % REGION_N != 0)
      $fatal(1, "%m: REGION_N = %0d, MESH_N = %0d; the region side must be a power of two that divides the mesh side",
             REGION_N, MESH_N);
    if (K_INIT < 0 || K_INIT >= (1 << KL_W))
      $fatal(1, "%m: K_INIT = %0d; k_L must be 0..%0d", K_INIT, (1 << KL_W) - 1);
    if (A_DLY < 1 || EPOCH <= A_DLY || EW < 1)
      $fatal(1, "%m: EPOCH = %0d, A_DLY = %0d; the plan must be sampled inside the epoch", EPOCH, A_DLY);
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/ctrl/demand_counter.sv
// =============================================================================
`timescale 1ns/1ps

module demand_counter
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int REGION_N = 4,
  parameter int NUM_VC   = 4
) (
  input  logic                         clk_i,
  input  logic                         rst_ni,
  input  coord_t                       cur_x_i,
  input  coord_t                       cur_y_i,
  input  logic                         tick_i,      // first cycle of an epoch
  input  flit_t      [NPORTS-1:0]      in_flit_i,   // the router's input links
  input  credit_t    [NPORTS-1:0]      in_cred_i,   // the credits it sends back on them
  output logic       [DM_W-1:0]        cl_o,        // last epoch: local occupancy sum
  output logic       [DM_W-1:0]        cg_o         // last epoch: cross-region occupancy sum
);

  localparam int NV  = NPORTS * NUM_VC;                // VCs counted
  localparam int PCW = $clog2(NV + 1);                 // a popcount
  localparam int SW  = $clog2(DM_SAMPLE);              // sample phase
  localparam int RGW = $clog2(REGION_N);               // coordinate bits inside a region

  logic [NPORTS-1:0][NUM_VC-1:0] occ_q, loc_q;
  logic [SW-1:0]                 ph_q;
  logic [DM_W-1:0]               al_q, ag_q, cl_q, cg_q;

  function automatic logic same_region(node_id_t d, coord_t x, coord_t y);
    coord_t dx, dy;
    dx = id_x(d, MESH_N);
    dy = id_y(d, MESH_N);
    return ((dx >> RGW) == (x >> RGW)) && ((dy >> RGW) == (y >> RGW));
  endfunction

  for (genvar p = 0; p < NPORTS; p++) begin : g_port
    head_t hd;
    logic  arr;
    assign hd  = head_t'(in_flit_i[p].data);
    assign arr = in_flit_i[p].vld & ~in_flit_i[p].byp & is_head(in_flit_i[p].ftype);

    for (genvar v = 0; v < NUM_VC; v++) begin : g_vc
      logic set, clr;
      assign set = arr & (in_flit_i[p].vc == vc_id_t'(v));
      assign clr = in_cred_i[p].vld & in_cred_i[p].vc_free & (in_cred_i[p].vc == vc_id_t'(v));

      always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
          occ_q[p][v] <= 1'b0;
          loc_q[p][v] <= 1'b0;
        end else if (set) begin               // a new packet (a free credit cannot come with it)
          occ_q[p][v] <= 1'b1;
          loc_q[p][v] <= same_region(hd.dst, cur_x_i, cur_y_i);
        end else if (clr) begin
          occ_q[p][v] <= 1'b0;
        end
      end
    end

    logic unused_hd;
    assign unused_hd = ^{hd.rsvd_hi, hd.check, hd.t_create, hd.seq, hd.len, hd.rsvd_lo, hd.cls, hd.src};
  end

  logic [PCW-1:0]  n_loc, n_glb;
  logic [DM_W:0]   nl_sum, ng_sum;                     // one bit more, for saturation
  logic            samp;

  always_comb begin
    n_loc = '0;
    n_glb = '0;
    for (int p = 0; p < NPORTS; p++) begin
      for (int v = 0; v < NUM_VC; v++) begin
        if (occ_q[p][v] &&  loc_q[p][v]) n_loc = n_loc + 1'b1;
        if (occ_q[p][v] && !loc_q[p][v]) n_glb = n_glb + 1'b1;
      end
    end
  end

  assign samp = tick_i | (ph_q == '0);

  always_comb begin
    logic [DM_W:0] bl, bg;
    bl = tick_i ? '0 : {1'b0, al_q};
    bg = tick_i ? '0 : {1'b0, ag_q};
    nl_sum = bl + (DM_W + 1)'(n_loc);
    ng_sum = bg + (DM_W + 1)'(n_glb);
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ph_q <= '0;
      al_q <= '0;
      ag_q <= '0;
      cl_q <= '0;
      cg_q <= '0;
    end else begin
      ph_q <= tick_i ? SW'(1) : ph_q + 1'b1;
      if (tick_i) begin
        cl_q <= al_q;
        cg_q <= ag_q;
      end
      if (samp) begin
        al_q <= nl_sum[DM_W] ? {DM_W{1'b1}} : nl_sum[DM_W-1:0];
        ag_q <= ng_sum[DM_W] ? {DM_W{1'b1}} : ng_sum[DM_W-1:0];
      end
    end
  end

  assign cl_o = cl_q;
  assign cg_o = cg_q;

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (REGION_N < 2 || REGION_N > MESH_N || (REGION_N & (REGION_N - 1)) != 0)
      $fatal(1, "%m: REGION_N = %0d, must be a power of two, 2..MESH_N", REGION_N);
    if ((MESH_N & (MESH_N - 1)) != 0)
      $fatal(1, "%m: MESH_N = %0d, must be a power of two", MESH_N);
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/ctrl/ctrl_node.sv
// =============================================================================
`timescale 1ns/1ps

module ctrl_node
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int MESH_N = 8,
  parameter int K_INIT = 4                 // plan from reset
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  coord_t           cur_x_i,
  input  coord_t           cur_y_i,
  input  logic             tick_i,         // first cycle of an epoch
  input  logic [DM_W-1:0]  cl_i,           // this tile's latched sums (demand_counter)
  input  logic [DM_W-1:0]  cg_i,
  input  logic [1:0]       sum_e_i,        // from the east neighbour
  input  logic [1:0]       sum_s_i,        // from the south neighbour (column 0)
  output logic [1:0]       sum_o,          // toward tile (0, 0)
  input  kl_t              plan_i,         // from upstream
  output kl_t              plan_o          // registered: sequencer, downstream
);

  localparam int SW = dm_sum_w(MESH_N);    // bits of the mesh-wide sums

  logic [CT_W-1:0] ct_q;                   // cycle since the last tick (tick = 0), saturating
  logic [1:0]      cl_c, cg_c;             // carries
  logic [1:0]      sum_q;
  kl_t             plan_q;

  logic [CT_W-1:0] t0, k;
  logic            act;

  assign t0  = CT_W'(2 * MESH_N - 1) - CT_W'(cur_x_i) - CT_W'(cur_y_i);
  assign k   = ct_q - t0;
  assign act = !tick_i && (ct_q >= t0) && (k < CT_W'(SW));

  logic       ol, og, se, ss_l, ss_g;
  logic [2:0] tl, tg;

  assign ol   = (k < CT_W'(DM_W)) ? cl_i[k[$clog2(DM_W)-1:0]] : 1'b0;
  assign og   = (k < CT_W'(DM_W)) ? cg_i[k[$clog2(DM_W)-1:0]] : 1'b0;
  assign se   = (cur_x_i == '0);           // column 0 also adds its south input
  assign ss_l = se & sum_s_i[0];
  assign ss_g = se & sum_s_i[1];
  assign tl   = 3'(ol) + 3'(sum_e_i[0]) + 3'(ss_l) + 3'(cl_c);
  assign tg   = 3'(og) + 3'(sum_e_i[1]) + 3'(ss_g) + 3'(cg_c);

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ct_q   <= '1;
      cl_c   <= '0;
      cg_c   <= '0;
      sum_q  <= '0;
      plan_q <= kl_t'(K_INIT);
    end else begin
      ct_q   <= tick_i ? CT_W'(1) : (ct_q == '1) ? ct_q : ct_q + 1'b1;
      plan_q <= plan_i;
      if (act) begin
        sum_q <= {tg[0], tl[0]};
        cl_c  <= tl[2:1];
        cg_c  <= tg[2:1];
      end else begin
        sum_q <= '0;
        cl_c  <= '0;
        cg_c  <= '0;
      end
    end
  end

  assign sum_o  = sum_q;
  assign plan_o = plan_q;

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (4 * MESH_N + SW + 8 > A_DELAY)
      $fatal(1, "%m: a %0dx%0d mesh cannot sum and forward the plan within A_DELAY = %0d", MESH_N, MESH_N, A_DELAY);
  end
  always_ff @(posedge clk_i) begin
    if (act && k == CT_W'(SW - 1) && (tl[2:1] != '0 || tg[2:1] != '0))
      $fatal(1, "%m: the demand sums overflow %0d bits", SW);
  end
  // synopsys translate_on
`endif

endmodule

// =============================================================================
// ==== rtl/ctrl/sched_ctrl.sv
// =============================================================================
`timescale 1ns/1ps

module sched_ctrl
  import sched_pkg::*;
#(
  parameter int MESH_N   = 8,
  parameter int REGION_N = 4,
  parameter int K_INIT   = 4,              // k_L from reset
  parameter int K_LO     = K_MIN,          // clamp (D18)
  parameter int K_HI     = k_max(MESH_N)
) (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  logic        tick_i,              // first cycle of an epoch
  input  logic [1:0]  sum_i,               // from tile (0, 0)'s ctrl_node
  input  logic        policy_i,            // POL_PROP (0) or POL_SQRT (1)
  input  logic        damp_i,              // damping on
  output kl_t         plan_o               // the plan, into tile (0, 0)
);

  localparam int SW = dm_sum_w(MESH_N);    // bits of each sum
  localparam int CS = ct_sums(MESH_N);     // cycle in which both sums are whole
  localparam int C0 = 2 * MESH_N;          // cycle in which bit 0 arrives

  logic [CT_W-1:0] ct_q;
  logic [SW-1:0]   sl_q, sg_q;             // the sums, shifted in
  logic [SW+1:0]   r_q, d_q;               // division: remainder, divisor S
  logic [4:0]      q_q;                    // share bin, 0..16
  kl_t             k_q;

  kl_t [15:0] tab_p, tab_s;
  for (genvar i = 0; i < 16; i++) begin : g_tab
    localparam int KP = kl_table(POL_PROP, MESH_N, REGION_N, K_LO, K_HI, i);
    localparam int KS = kl_table(POL_SQRT, MESH_N, REGION_N, K_LO, K_HI, i);
    assign tab_p[i] = kl_t'(KP);
    assign tab_s[i] = kl_t'(KS);
  end

  logic          shift, load, step0, stepk, upd;
  logic [SW+1:0] r2;
  kl_t           kt, kc, kd, kn;
  logic [6:0]    ks;

  assign shift = (ct_q >= CT_W'(C0)) && (ct_q < CT_W'(CS)) && !tick_i;
  assign load  = (ct_q == CT_W'(CS)) && !tick_i;
  assign step0 = (ct_q == CT_W'(CS + 1)) && !tick_i;
  assign stepk = (ct_q >= CT_W'(CS + 2)) && (ct_q <= CT_W'(CS + 5)) && !tick_i;
  assign upd   = (ct_q == CT_W'(CS + 6)) && !tick_i;

  assign r2 = {r_q[SW:0], 1'b0};

  always_comb begin
    if (d_q == '0)
      kt = k_q;
    else if (q_q[4])
      kt = kl_t'(K_HI);
    else if (policy_i)
      kt = tab_s[q_q[3:0]];
    else
      kt = tab_p[q_q[3:0]];
    if (kt < kl_t'(K_LO))
      kc = kl_t'(K_LO);
    else if (kt > kl_t'(K_HI))
      kc = kl_t'(K_HI);
    else
      kc = kt;
    ks = 7'(k_q) + 7'(kc) + 7'(kc > k_q);
    kd = damp_i ? ks[KL_W:1] : kc;
    if (kd < kl_t'(K_LO))
      kn = kl_t'(K_LO);
    else if (kd > kl_t'(K_HI))
      kn = kl_t'(K_HI);
    else
      kn = kd;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ct_q <= '1;
      sl_q <= '0;
      sg_q <= '0;
      r_q  <= '0;
      d_q  <= '0;
      q_q  <= '0;
      k_q  <= kl_t'(K_INIT);
    end else begin
      ct_q <= tick_i ? CT_W'(1) : (ct_q == '1) ? ct_q : ct_q + 1'b1;
      if (shift) begin
        sl_q <= {sum_i[0], sl_q[SW-1:1]};
        sg_q <= {sum_i[1], sg_q[SW-1:1]};
      end
      if (load) begin
        r_q <= {2'b00, sl_q};
        d_q <= {2'b00, sl_q} + {2'b00, sg_q};
        q_q <= '0;
      end
      if (step0) begin                      // weight 16: C_L = S, so C_G = 0
        if (r_q >= d_q) begin
          r_q    <= r_q - d_q;
          q_q[4] <= 1'b1;
        end
      end
      if (stepk) begin                      // weights 8, 4, 2, 1, into q_q[3:0]
        if (r2 >= d_q) begin
          r_q      <= r2 - d_q;
          q_q[3:0] <= {q_q[2:0], 1'b1};
        end else begin
          r_q      <= r2;
          q_q[3:0] <= {q_q[2:0], 1'b0};
        end
      end
      if (upd) k_q <= kn;
    end
  end

  assign plan_o = k_q;

  logic unused_ks;
  assign unused_ks = ks[0];

`ifndef SYNTHESIS
  // synopsys translate_off
  initial begin
    if (K_LO < 0 || K_HI < K_LO || K_HI >= (1 << KL_W))
      $fatal(1, "%m: clamp [%0d, %0d] outside 0..%0d", K_LO, K_HI, (1 << KL_W) - 1);
    if (CS + 6 + 2 * MESH_N > A_DELAY - 1)
      $fatal(1, "%m: the plan would reach the last tile after the sample (cycle %0d)", A_DELAY - 1);
  end
  // synopsys translate_on
`endif

endmodule
